import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { fetchMachinesForCurrentUser, createMachine } from '../services/api';

export default function DashboardPage() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [loading, setLoading] = useState(false);
  const [notFound, setNotFound] = useState(false);

  // Активная вкладка: 'info' (Общая информация), 'TO', 'claims'
  const [activeTab, setActiveTab] = useState('info');

  const [machines, setMachines] = useState([]);
  const [filters, setFilters] = useState({ 
    model_machine: '',
    model_engine: '',
    model_transmission: '',
    model_controlled_bridge: '',
    model_driving_bridge: '',
    serial_number_machine: '',
  });

  // Надёжное определение Manager. Может приходить как string, или массив объектов/строк
  const isManager = React.useMemo(() => {
    if (!user) return false;
    const groupField = user.groups ?? []; // может быть массив строк/объектов
    if (Array.isArray(groupField) && groupField.length > 0) {
      // если это массив строк
      if (groupField.every(g => typeof g === 'string')) {
        return groupField.includes('Manager') || groupField.includes('manager');
      }
      // если это массив объектов
      if (groupField[0] && typeof groupField[0] === 'object') {
        return groupField.some(g => (g.name ?? '').toString() === 'Manager');
      }
    }
    // альтернативно простое поле group
    if (typeof user.group === 'string') {
      return user.group === 'Manager';
    }
    return false;
  }, [user]);

  // кнопка создания новой машины
  const [showCreate, setShowCreate] = useState(false);

  const handleCreate = async (payload) => { 
    try { 
      await createMachine(payload);
      setShowCreate(false);
      // можно перезагрузить список
      const data = await fetchMachinesForCurrentUser();
      setMachines(Array.isArray(data) ? data : []);
    } catch (e) { console.error(e); }
  };

  // Машина: отдельный компонент формы создания
  const MachineCreateForm = ({ onSubmit, onCancel }) => { 
    const [serial, setSerial] = useState(''); 
    const [model, setModel] = useState(''); 
    const [customerId, setCustomerId] = useState(''); 
    const [serviceCompanyId, setServiceCompanyId] = useState(''); 

    const handleSubmit = (e) => { 
      e.preventDefault(); 
      const payload = { 
        serial_number_machine: serial, 
        model_machine: model,
        customer: customerId || null,
        service_company: serviceCompanyId || null,
      }; 
      onSubmit(payload); 
    };

    return ( 
      <form onSubmit={handleSubmit}> 
        <div>
          <label>Серийный номер</label>
          <input value={serial} onChange={(e) => setSerial(e.target.value)} />
        </div> 
        <div>
          <label>Модель машины</label>
          <input value={model} onChange={(e) => setModel(e.target.value)} />
        </div> 
        <div>
          <label>Customer (id)</label>
          <input value={customerId} onChange={(e) => setCustomerId(e.target.value)} />
        </div> 
        <div>
          <label>ServiceCompany (id)</label>
          <input value={serviceCompanyId} onChange={(e) => setServiceCompanyId(e.target.value)} />
        </div> 
        <button type="submit">Создать</button> 
        <button type="button" onClick={onCancel}>Отмена</button> 
      </form> 
    ); 
  };

  // Загрузка данных машин при переходе во вкладку "Общая информация"
  useEffect(() => {
    if (activeTab !== 'info') return;

    const loadMachines = async () => {
      try {
        const data = await fetchMachinesForCurrentUser();
        setMachines(Array.isArray(data) ? data : []);
      } catch {
        setNotFound(true);
      } finally {
        setLoading(false);
      }
    };

    setLoading(true);
    loadMachines();
  }, [activeTab]);

  // Фильтрация
  const getDisplayValue = (m, key) => { 
    const v = m?.[key]; 
    if (v && typeof v === 'object') { return v.name ?? v.id ?? ''; } 
    return v ?? ''; 
  };

  const filteredMachines = useMemo(() => { 
    return machines.filter((m) => { 
        const mm = String(getDisplayValue(m, 'model_machine')).toLowerCase();
        const me = String(getDisplayValue(m, 'model_engine')).toLowerCase();
        const tr = String(getDisplayValue(m, 'model_transmission')).toLowerCase();
        const cb = String(getDisplayValue(m, 'model_controlled_bridge')).toLowerCase();
        const db = String(getDisplayValue(m, 'model_driving_bridge')).toLowerCase(); 
        const sn = String(m?.serial_number_machine ?? '').toLowerCase();
        const f1 = filters.model_machine ? mm.includes(filters.model_machine.toLowerCase()) : true;
        const f2 = filters.model_engine ? me.includes(filters.model_engine.toLowerCase()) : true;
        const f3 = filters.model_transmission ? tr.includes(filters.model_transmission.toLowerCase()) : true;
        const f4 = filters.model_controlled_bridge ? cb.includes(filters.model_controlled_bridge.toLowerCase()) : true;
        const f5 = filters.model_driving_bridge ? db.includes(filters.model_driving_bridge.toLowerCase()) : true;
        const f6 = filters.serial_number_machine ? sn.includes(filters.serial_number_machine.toLowerCase()) : true;

        return f1 && f2 && f3 && f4 && f5 && f6;
    });
  }, [machines, filters]);

  const handleRowClick = (machine) => { 
    if (!machine?.id) return; navigate(`/machines/${machine.id}`); 
  };
  const handleFilterChange = (e) => { 
    const { name, value } = e.target; setFilters((f) => ({ ...f, [name]: value })); 
  };

  // Рендер
  return (
    <div className="dashboard-page" style={{ padding: 16 }}>
      <div className="page-header" style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
        <h2>Панель управления</h2>
      </div>

      <div className="user-name" style={{ marginTop: 8, marginBottom: 16 }}>
        Вы вошли как: {user?.username || 'Пользователь'}
      </div>

      {isManager && (
        <div style={{ marginBottom: 8 }}>
          <button onClick={() => setShowCreate(true)}>
            Создать новую машину
          </button>
        </div>
      )}

      {showCreate && (
        <MachineCreateForm
          onSubmit={handleCreate}
          onCancel={() => setShowCreate(false)}
        />
      )}

      <div className="dashboard-tabs" style={{ display: 'flex', gap: 8, marginBottom: 12 }}>
        <button onClick={() => setActiveTab('info')} className={activeTab === 'info' ? 'active' : ''}>
          Общая информация
        </button>
        <button onClick={() => setActiveTab('TO')} className={activeTab === 'TO' ? 'active' : ''}>
          ТО
        </button>
        <button onClick={() => setActiveTab('claims')} className={activeTab === 'claims' ? 'active' : ''}>
          Рекламации
        </button>
      </div>

      {loading && <div>Загрузка...</div>}

      {!loading && notFound && (
        <div>Не удалось загрузить данные машин.</div>
      )}

      {!loading && !notFound && activeTab === 'info' && (
        <div>
          <div className="filters" style={{ display: 'flex', gap: 8, margin: '8px 0 12px 0' }}>
            <input placeholder="Машина" name="model_machine" value={filters.model_machine} onChange={handleFilterChange} />
            <input placeholder="Двигатель" name="model_engine" value={filters.model_engine} onChange={handleFilterChange} />
            <input placeholder="Трансмиссия" name="model_transmission" value={filters.model_transmission} onChange={handleFilterChange} />
            <input placeholder="Упр.мост" name="model_controlled_bridge" value={filters.model_controlled_bridge} onChange={handleFilterChange} />
            <input placeholder="Вед.мост" name="model_driving_bridge" value={filters.model_driving_bridge} onChange={handleFilterChange} />
            <input placeholder="SN машины" name="serial_number_machine" value={filters.serial_number_machine} onChange={handleFilterChange} />
          </div> 

          {machines.length === 0 ? (
            <div>Нет машин для отображения.</div>
          ) : (
            <table border="1" cellPadding="6" cellSpacing="0">
              <thead>
                <tr>
                  <th>Дата отгрузки</th>
                  <th>Модель машины</th>
                  <th>Серийный номер машины</th>
                  <th>Модель двигателя</th>
                  <th>Модель трансмиссии</th>
                  <th>Модель упр.моста</th>
                  <th>Модель ведущего моста</th>
                </tr>
              </thead>
              <tbody>
                {filteredMachines.map((m) => (
                  <tr key={m.id} 
                    onClick={() => handleRowClick(m)} 
                    style={{ cursor: 'pointer' }} 
                    role="button" 
                    tabIndex={0} 
                    onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { handleRowClick(m); } }} 
                    aria-label={`Перейти к данным машины ${m.serial_number_machine ?? ''}`} > 
                    <td>{m.date_shipment_from_factory}</td>
                    <td>
                      {m.model_machine
                        ? typeof m.model_machine === 'object'
                          ? (m.model_machine.name || m.model_machine.id || '')
                          : m.model_machine
                        : ''}
                    </td>
                    <td>{m.serial_number_machine ?? ''}</td>        
                    <td>
                      {m.model_engine
                        ? typeof m.model_engine === 'object'
                          ? (m.model_engine.name || m.model_engine.id || '')
                          : m.model_engine
                        : ''}
                    </td>
                    <td>
                      {m.model_transmission
                        ? typeof m.model_transmission === 'object'
                          ? (m.model_transmission.name || m.model_transmission.id || '')
                          : m.model_transmission
                        : ''}
                    </td>
                    <td>
                      {m.model_controlled_bridge
                        ? typeof m.model_controlled_bridge === 'object'
                          ? (m.model_controlled_bridge.name || m.model_controlled_bridge.id || '')
                          : m.model_controlled_bridge
                        : ''}
                    </td>
                    <td>
                      {m.model_driving_bridge
                        ? typeof m.model_driving_bridge === 'object'
                          ? (m.model_driving_bridge.name || m.model_driving_bridge.id || '')
                          : m.model_driving_bridge
                        : ''}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}
    </div>
  );
}
